properties.query:
let windowSize = 2h;
let repeatGate = toscalar(_GetWatchlist('UAV_Threshold_List') | where ThresholdKey == 'MinAutoCollectReadCount' | project toint(Value));
let bytesGate = toscalar(_GetWatchlist('UAV_Threshold_List') | where ThresholdKey == 'MaxSatcomExfilBytes' | project tolong(Value));
let archiveTools = dynamic(["tar","zip","gzip","7z","rar","zstd"]);

// S127: Automated Collection (연결키: ContainerName)
let S127 =
    UAVFileAudit_CL
    | where TimeGenerated > ago(windowSize)
    | where Operation == "read"
    | summarize ReadCount = count(), LastEvent = max(TimeGenerated) by ContainerName, ProcessName, FilePath, User
    | where ReadCount >= repeatGate;
// S128: Archive Collected Data — 전역 게이트
let S128Time = toscalar(
    UAVFileAudit_CL
    | where TimeGenerated > ago(windowSize)
    | where Operation in ("exec","write")
    | where ProcessName has_any (archiveTools) or FilePath endswith ".tar" or FilePath endswith ".zip" or FilePath endswith ".gz"
    | summarize min(TimeGenerated));
// S65: SATCOM/Web Exfil — 전역 게이트
let S65Time = toscalar(
    UAVSatcomLink_CL
    | where TimeGenerated > ago(windowSize)
    | summarize TotalBytes = sum(PayloadBytes), LastEvent = max(TimeGenerated) by UAVId, LinkId
    | where TotalBytes > bytesGate
    | summarize min(LastEvent));
S127
| extend HasS128 = isnotnull(S128Time), HasS65 = isnotnull(S65Time)
| where HasS128 or HasS65
| extend CampaignType = "C34_자동수집_아카이브_SATCOM유출"
| extend StepSummary = strcat("S127@", tostring(LastEvent), " | S128(전역)@", tostring(S128Time), " | S65(전역)@", tostring(S65Time))
| extend Severity = "High"
| project TimeGenerated = LastEvent, ContainerName, ProcessName, FilePath, User, S128Time, S65Time, CampaignType, StepSummary, Severity
